    ui = preparerInterface(c, { largeur: 412, hauteur: 900 });
    ecran = ecranEau.monter(ui.parId('ecran-eau'), { raf: h.raf, caf: h.caf, reglages: { fond: 'image', dureeSortieMs: 0, image: 'eau/image-FICTIVE.png' } });
